INSERT OR IGNORE INTO titles (id, title, type, year, episodes, minutes, synopsis, genre, hue, platforms, tags, source, review_status) VALUES (1, 'Cartas desde el faro', 'Serie', 2025, 10, 0, 'Una restauradora llega a un faro abandonado de la costa gallega y encuentra cartas sin remitente. Cada una la acerca a un secreto del pueblo y a quien las escribió.', 'Misterio', 350, '["Netflix"]', '["Slow burn","Para llorar"]', 'base', 'approved');
