INSERT OR IGNORE INTO titles (id, title, type, year, episodes, minutes, synopsis, genre, hue, platforms, tags, source, review_status) VALUES (3, 'Hasta que cierre el café', 'Serie', 2024, 12, 0, 'En una cafetería de barrio a punto de cerrar, el personal y los clientes de siempre se unen para salvarla. Una serie pequeña, cálida y de las que abrazan.', 'Cozy', 150, '["Filmin","Movistar+"]', '["Comfort","Para desconectar"]', 'base', 'approved');
INSERT OR IGNORE INTO titles (id, title, type, year, episodes, minutes, synopsis, genre, hue, platforms, tags, source, review_status) VALUES (4, 'Primavera en Seúl', 'Serie', 2025, 16, 0, 'Una traductora viaja a Seúl por trabajo y se queda más tiempo del previsto. Una historia lenta sobre empezar de cero lejos de casa.', 'Drama', 165, '["Netflix"]', '["Slow burn","Para llorar"]', 'base', 'approved');
INSERT OR IGNORE INTO titles (id, title, type, year, episodes, minutes, synopsis, genre, hue, platforms, tags, source, review_status) VALUES (5, 'Noches de invierno', 'Serie', 2023, 6, 0, 'Un grupo de amigas se reúne cada invierno en una casa de montaña. Esta vez, una invitada inesperada lo cambia todo.', 'Misterio', 220, '["Movistar+"]', '["Para ver con amigas"]', 'base', 'approved');
