INSERT OR IGNORE INTO titles (id, title, type, year, episodes, minutes, synopsis, genre, hue, platforms, tags, source, review_status) VALUES (7, 'Vuelve a casa', 'Película', 2026, 1, 112, 'Tras años fuera, una mujer vuelve al pueblo para vender la casa de su abuela. Entre cajas y recuerdos, tendrá que decidir si se queda.', 'Drama', 50, '["Disney+","Prime Video"]', '["Para llorar","Comfort"]', 'base', 'approved');
